command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="b414e8e3f8eb5e6c771c1f41ba4e632c143b1db4"
$branch="work/removable-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "branch cleanup fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($observed -ne $main){throw "main moved before branch cleanup"}
$remoteRef="refs/remotes/origin/"+$branch
& git show-ref --verify --quiet $remoteRef
if($LASTEXITCODE -ne 0){throw "temporary work branch is already absent or unresolved"}
$branchHead=(& git rev-parse $remoteRef).Trim()
if($branchHead -ne $main){throw "temporary branch does not point at accepted main"}
& git merge-base --is-ancestor $branchHead $observed
if($LASTEXITCODE -ne 0){throw "temporary branch is not merged into main"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "temporary branch deletion failed"}
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "post-cleanup fetch failed"}
& git show-ref --verify --quiet $remoteRef
if($LASTEXITCODE -eq 0){throw "temporary work branch still exists after deletion"}
Write-Host "REMOVABLE_SHELL_VISUAL_WORK_BRANCH_CLEANUP=PASS"
